//! Vectors for `derive()` with the default `FrameShape`, generated by
//! `scripts/cpp_vectors/frame_derive_vectors.cpp` from `fixtures/config/policy.txt`.

use std::collections::HashMap;
use std::fs;
use std::path::Path;

use fp_core::frame::derive::{derive, FrameShape};
use fp_core::frame::parameters::read_parameters;
use fp_core::numbers::blocks::{GroupSize, Stage};

const VECTORS: &str = include_str!("../../fixtures/frame_derive_vectors.txt");

fn unhex(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    assert!(b.len() % 2 == 0, "odd hex length");
    let mut v = Vec::with_capacity(b.len() / 2);
    for p in b.chunks_exact(2) {
        v.push((hexval(p[0]) << 4) | hexval(p[1]));
    }
    v
}

fn hexval(c: u8) -> u8 {
    match c {
        b'0'..=b'9' => c - b'0',
        b'a'..=b'f' => c - b'a' + 10,
        _ => panic!("bad hex digit {}", c as char),
    }
}

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

fn group_str(g: &GroupSize) -> String {
    format!(
        "name={} main={},{},{},{} mask={},{},{},{} k={} h={} slots={} rule={} m={}",
        hex(&g.name.as_bytes().to_vec()),
        g.main.log_n,
        g.main.ell,
        g.main.r,
        g.main.over_e as u8,
        g.mask.log_n,
        g.mask.ell,
        g.mask.r,
        g.mask.over_e as u8,
        g.k,
        g.h,
        g.slots,
        g.rule as u8,
        g.m
    )
}

fn hex(b: &[u8]) -> String {
    let mut s = String::new();
    for x in b {
        s.push_str(&format!("{x:02x}"));
    }
    s
}

fn check_test(line: &str, got_name: &str, t: &fp_core::frame::derive::TestSizes) {
    let kv = fields(line);
    assert_eq!(kv["name"], got_name, "test name");
    assert_eq!(kv["t"], t.t.to_string(), "{}: t", got_name);
    assert_eq!(
        line.split_once("group=").unwrap().1.split(" stages=").next().unwrap(),
        group_str(&t.group),
        "{}: group",
        got_name
    );
    assert_eq!(kv["stages"], t.stages.len().to_string(), "{}: stage count", got_name);
}

fn check_stage(line: &str, got: &Stage) {
    let kv = fields(line);
    assert_eq!(kv["t"], got.t.to_string(), "stage t");
    assert_eq!(kv["r_ood"], got.r_ood.to_string(), "stage r_ood");
    assert_eq!(
        line.split_once("group=").unwrap().1.split(" stages=").next().unwrap(),
        group_str(&got.g),
        "stage group"
    );
}

#[test]
fn frame_derive_matches_the_cpp_reference() {
    let at = Path::new(env!("CARGO_MANIFEST_DIR")).join("../fixtures/config/policy.txt");
    let text = fs::read(at).unwrap();
    let mut p = fp_core::frame::parameters::Parameters::default();
    read_parameters(&text, &mut p).unwrap();
    let d = derive(&p, &FrameShape::default());

    let mut lines = VECTORS.lines();
    let first = fields(lines.next().unwrap());
    let refused = if first["refused"] == "-" { String::new() } else { String::from_utf8(unhex(first["refused"])).unwrap() };
    assert_eq!(d.refused, refused, "refusal");
    assert_eq!(first["target"], d.set.target.to_string(), "target");
    assert_eq!(first["samples"], d.set.samples.to_string(), "samples");
    assert_eq!(first["salt"], d.set.salt_bytes.to_string(), "salt");
    let work: Vec<u32> = first["work"].split(',').map(|x| x.parse().unwrap()).collect();
    for i in 0..6 {
        for j in 0..3 {
            assert_eq!(d.set.work[i][j], work[i * 3 + j], "work[{}][{}]", i, j);
        }
    }

    let line = lines.next().unwrap();
    check_test(line, "link", &d.link);
    let line = lines.next().unwrap();
    check_test(line, "last", &d.last);
    for st in &d.last.stages {
        let line = lines.next().unwrap();
        assert!(line.starts_with("STAGE "), "{}", line);
        check_stage(line, st);
    }
    let table = fields(lines.next().unwrap());
    assert_eq!(table["log_n"], d.table.code.log_n.to_string(), "table log_n");
    assert_eq!(table["ell"], d.table.code.ell.to_string(), "table ell");
    assert_eq!(table["r"], d.table.code.r.to_string(), "table r");
    assert_eq!(table["v"], d.table.v.to_string(), "table v");
    assert_eq!(table["answers"], d.table.answers.to_string(), "table answers");
    assert_eq!(table["radius"], d.table.distances.radius.to_string(), "radius");
    assert_eq!(table["later"], d.table.distances.later_radius.to_string(), "later radius");
    assert_eq!(table["m_once"], d.table.distances.m_once.to_string(), "m_once");
    assert_eq!(table["m_later"], d.table.distances.m_later.to_string(), "m_later");
    assert!(lines.next().is_none(), "extra vector lines");
}
